from __future__ import annotations

from pathlib import Path
from typing import Any

from society.visualizer import HTML as SOCIETY_HTML
from society.visualizer import _json, _replace

HIERARCHY_CSS = r'''
.propagation-mode{position:relative;z-index:2;margin:12px 0;padding:8px 10px;border:1px solid #79c8ef55;border-radius:9px;background:#061d3b55;color:#dff4ff;font-size:11px}.propagation-mode b{color:#79daf6}.hierarchy-expand{cursor:pointer;pointer-events:all;fill:#fff!important;stroke:#174b8a;stroke-width:1.4}.hierarchy-expand-label{cursor:pointer;pointer-events:all;fill:#174b8a!important;font-size:13px!important;font-weight:950!important}.argument-subagent{cursor:pointer}.argument-subagent rect{fill:#fff;stroke:#4c7ec0;stroke-width:2;filter:drop-shadow(0 3px 5px #17304f2b)}.argument-subagent.active rect{fill:#eff8ff}.argument-subagent.historical{opacity:.67}.argument-subagent.selected rect{stroke:var(--cyan);stroke-width:3.5;filter:drop-shadow(0 0 7px #00a8c766)}.argument-subagent text{text-anchor:middle;pointer-events:none;fill:#162743;font-size:9px;font-weight:850}.argument-subagent .arg-sub{fill:#5c6c80;font-size:8px;font-weight:650}.canonical-child-edge{fill:none;stroke-width:2;stroke-linecap:round;opacity:.78}.canonical-child-edge.support{stroke:var(--green)}.canonical-child-edge.attack{stroke:var(--red)}.canonical-child-label{font-size:7px;font-weight:900;fill:#476078;paint-order:stroke;stroke:#fff;stroke-width:3px;text-anchor:middle}.argument-agent-section{margin-top:14px;padding-top:10px;border-top:1px solid #dce5ef}.argument-agent-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.argument-agent-stat{padding:7px 8px;border-radius:7px;background:#eef5ff;font-size:10px}.argument-agent-list{display:grid;gap:5px;margin-top:7px}.argument-agent-button{padding:7px 8px;border:1px solid #cfdae7;border-radius:7px;background:#fff;color:#174b8a;text-align:left;cursor:pointer;font-size:10px}.argument-agent-button:hover{border-color:#4c7ec0;background:#f2f7ff}.propagation-card{margin:6px 0;padding:8px;border:1px solid #dfe7f0;border-left:4px solid #00a8c7;border-radius:7px;background:#f7fbff;font-size:10px}.propagation-card.queued{border-left-color:#9aa7b7;border-style:dashed}.propagation-card b{color:#174b8a}.hierarchy-note{margin-top:7px;color:var(--muted);font-size:10px}
'''


HIERARCHY_JS = r'''
const expandedViewpoints=new Set((params.get('expand')||'').split(',').filter(id=>TRACE.agent_hierarchy[id])),argumentAgentById=Object.fromEntries(Object.values(TRACE.argument_subagents).map(a=>[a.argument_id,a]));let hierarchySelectedArgument=null;
const MESSAGE_LABEL={ARGUMENT_AVAILABLE:'LẬP LUẬN KHẢ DỤNG',SUPPORT:'ỦNG HỘ',ATTACK:'TẤN CÔNG',CHALLENGE:'CHẤT VẤN',PROVIDE_EVIDENCE:'CUNG CẤP BẰNG CHỨNG',RETRACTION:'RÚT LẬP LUẬN',REVISION_SIGNAL:'TÍN HIỆU ĐIỀU CHỈNH'};
function hierarchyAtOrBefore(t,k,mt,mk){const ti=TRACE.timestamps.findIndex(r=>r.timestamp===t),mi=TRACE.timestamps.findIndex(r=>r.timestamp===mt);return mi<ti||(mi===ti&&mk<=k)}
function hierarchyArgumentState(argumentId){return Object.values(current().step.argument_subagents||{}).find(a=>a.argument_id===argumentId)}
function hierarchyChildPosition(parentId,index,total){const p=positions(layoutIds)[parentId],angle=-Math.PI/2+(index+1)*2*Math.PI/(total+1),radius=128;return{x:Math.max(70,Math.min(1030,p.x+Math.cos(angle)*radius)),y:Math.max(38,Math.min(642,p.y+Math.sin(angle)*radius))}}
function hierarchyEndpoint(argumentId,childPositions){const owner=TRACE.argument_owner[argumentId];return expandedViewpoints.has(owner)&&childPositions[argumentId]?childPositions[argumentId]:positions(layoutIds)[owner]}
function decorateHierarchyGraph(){const step=current().step,nodes=$('nodes'),edges=$('edges'),childPositions={};document.querySelectorAll('.agent').forEach(node=>{const id=node.dataset.id,toggle=document.createElementNS('http://www.w3.org/2000/svg','g');toggle.setAttribute('class','hierarchy-toggle');toggle.innerHTML=`<circle class="hierarchy-expand" cx="151" cy="12" r="10"></circle><text class="hierarchy-expand-label" x="151" y="16">${expandedViewpoints.has(id)?'−':'+'}</text>`;toggle.onpointerdown=e=>e.stopPropagation();toggle.onclick=e=>{e.stopPropagation();expandedViewpoints.has(id)?expandedViewpoints.delete(id):expandedViewpoints.add(id);render()};node.appendChild(toggle)});let childHtml='';for(const parentId of [...expandedViewpoints].sort()){const childIds=TRACE.agent_hierarchy[parentId]||[],visible=childIds.map(id=>step.argument_subagents[id]).filter(Boolean);visible.forEach((a,index)=>{const p=hierarchyChildPosition(parentId,index,visible.length);childPositions[a.argument_id]=p;const cat=TRACE.argument_catalog[a.argument_id],short=cat.conclusion.length>24?cat.conclusion.slice(0,23)+'…':cat.conclusion;childHtml+=`<g class="argument-subagent ${a.active?'active':'historical'} ${hierarchySelectedArgument===a.argument_id?'selected':''}" data-argument-agent="${esc(a.argument_id)}" transform="translate(${p.x-68} ${p.y-31})"><rect width="136" height="62" rx="10"/><text x="68" y="17">${esc(a.agent_id)}</text><text class="arg-sub" x="68" y="34">${esc(short)}</text><text class="arg-sub" x="68" y="49">${esc(a.belief_status)} · ${a.confidence.toFixed(3)}</text></g>`})}nodes.insertAdjacentHTML('beforeend',childHtml);let relationHtml='';for(const r of TRACE.argument_relations_by_timestamp[current().run.timestamp]||[]){const sourceVisible=hierarchyArgumentState(r.source),targetVisible=hierarchyArgumentState(r.target);if(!sourceVisible||!targetVisible)continue;const sourceOwner=TRACE.argument_owner[r.source],targetOwner=TRACE.argument_owner[r.target];if(!expandedViewpoints.has(sourceOwner)&&!expandedViewpoints.has(targetOwner))continue;const a=hierarchyEndpoint(r.source,childPositions),b=hierarchyEndpoint(r.target,childPositions);if(!a||!b||sourceOwner===targetOwner&&!expandedViewpoints.has(sourceOwner))continue;const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,startPad=expandedViewpoints.has(sourceOwner)?72:88,endPad=expandedViewpoints.has(targetOwner)?72:88,sx=a.x+ux*startPad,sy=a.y+uy*startPad,ex=b.x-ux*endPad,ey=b.y-uy*endPad,marker=r.relation_type==='support'?'arrowGreen':'arrowRed';relationHtml+=`<g class="hierarchy-canonical-layer"><path class="canonical-child-edge ${esc(r.relation_type)}" d="M${sx} ${sy} L${ex} ${ey}" marker-end="url(#${marker})"/><text class="canonical-child-label" x="${(sx+ex)/2}" y="${(sy+ey)/2-4}">${esc(r.id)}</text></g>`}edges.insertAdjacentHTML('beforeend',relationHtml);document.querySelectorAll('[data-argument-agent]').forEach(node=>{const argumentId=node.dataset.argumentAgent,a=hierarchyArgumentState(argumentId),cat=TRACE.argument_catalog[argumentId];node.onmouseenter=e=>showTip(e,`<b>${esc(a.agent_id)} · ${esc(argumentId)}</b>${esc(cat.conclusion)}<small>${esc(a.belief_status)} · confidence ${a.confidence.toFixed(3)} · ${a.active?'active':'historical'}<br>Bấm để xem truyền tin và provenance.</small>`);node.onmousemove=e=>showTip(e,$('hoverTip').innerHTML);node.onmouseleave=hideTip;node.onclick=e=>{e.stopPropagation();hideTip();hierarchySelectedArgument=argumentId;state.agent=a.parent_viewpoint_ids[0];state.edge=null;activateReasoningTab();render()}})}
function hierarchyMessageCard(m){const delivered=m.delivered_at_t?`${esc(m.delivered_at_t)} / k${m.delivered_at_k}`:'chưa giao',consumed=m.consumed_at_t?`${esc(m.consumed_at_t)} / k${m.consumed_at_k}`:'chưa đọc';return`<div class="propagation-card ${m.delivery_status==='queued'?'queued':''}"><b>${esc(m.message_id)} · ${esc(MESSAGE_LABEL[m.message_type]||m.message_type)}</b><br>Gửi ${esc(m.sent_at_t)} / k${m.sent_at_k} · trễ ${m.delay_steps}k<br>Khả dụng ${esc(m.available_at_t)} / k${m.available_at_k} · giao ${delivered} · đọc ${consumed}<br>${esc(m.source_agent_id)} → ${esc(m.target_agent_id)}<br><small>Quan hệ: ${m.relation_ids.map(esc).join(', ')||'—'} · Nguồn: ${m.source_ids.map(esc).join(', ')||'—'} · tiếp xúc thực: chưa biết</small></div>`}
function enhanceHierarchyPanel(){if(state.edge!==null)return;const id=state.agent;if(!id)return;const macro=current().step.viewpoint_macro_agents?.[id];if(!macro)return;const panel=$('reasoning'),section=document.createElement('section');section.className='argument-agent-section';const rows=(TRACE.agent_hierarchy[id]||[]).map(agentId=>current().step.argument_subagents?.[agentId]).filter(Boolean);section.innerHTML=`<h3>ARGUMENT AGENTS</h3><div class="argument-agent-grid"><div class="argument-agent-stat"><b>${rows.length}</b><br>subagent khả dụng</div><div class="argument-agent-stat"><b>${macro.active_argument_count}</b><br>đang active</div><div class="argument-agent-stat"><b>${macro.accepted_count}/${macro.rejected_count}/${macro.undecided_count}</b><br>chấp nhận / bác / chưa quyết</div><div class="argument-agent-stat"><b>${macro.mean_confidence.toFixed(3)}</b><br>confidence trung bình</div><div class="argument-agent-stat"><b>${macro.disagreement.toFixed(3)}</b><br>phân kỳ</div><div class="argument-agent-stat"><b>${macro.cohesion.toFixed(3)}</b><br>gắn kết</div></div><div class="argument-agent-list">${rows.map(a=>`<button class="argument-agent-button" data-hierarchy-arg="${esc(a.argument_id)}"><b>${esc(a.agent_id)}</b> · ${esc(a.belief_status)} · ${a.confidence.toFixed(3)}</button>`).join('')||'<div class="card">Chưa có subagent khả dụng.</div>'}</div><p class="hierarchy-note">Macro-agent tổng hợp từ trạng thái argument agent; mapping canonical không đổi.</p>`;if(hierarchySelectedArgument&&TRACE.argument_owner[hierarchySelectedArgument]===id){const a=hierarchyArgumentState(hierarchySelectedArgument),cat=TRACE.argument_catalog[hierarchySelectedArgument],messages=TRACE.message_trace.filter(m=>(m.source_argument_id===hierarchySelectedArgument||m.target_argument_id===hierarchySelectedArgument)&&hierarchyAtOrBefore(current().run.timestamp,current().step.deliberation_step,m.sent_at_t,m.sent_at_k));section.innerHTML+=`<h3>INSPECTOR TRUYỀN TIN · ${esc(a.agent_id)}</h3><div class="argument-detail"><b>${esc(a.argument_id)}</b> · ${esc(a.belief_status)} · ${a.confidence.toFixed(3)}<br>${esc(cat.conclusion)}<br><small>${esc(a.active?'active':'historical')} · parent ${esc(a.parent_viewpoint_ids[0])}</small></div>${messages.slice(-12).map(hierarchyMessageCard).join('')||'<div class="card">Chưa có message gửi/nhận tới bước này.</div>'}`}panel.appendChild(section);panel.querySelectorAll('[data-hierarchy-arg]').forEach(button=>button.onclick=()=>{hierarchySelectedArgument=button.dataset.hierarchyArg;expandedViewpoints.add(id);render()})}
function initHierarchy(){const brand=document.querySelector('.brand'),box=document.createElement('div');box.className='propagation-mode';const p=TRACE.propagation_assumption;box.innerHTML=`<b>TRUYỀN TIN</b><br>${p.mode==='zero_delay'?'Không trễ (δ = 0)':`Trễ cố định ${p.default_delay_steps}k`}<br><small>Tiếp xúc thực tế: chưa biết</small>`;brand.insertBefore(box,brand.querySelector('.loop'));}
'''


def _template() -> str:
    html = SOCIETY_HTML
    html = _replace(html, "<title>VIP Girls Society — Xã hội tác tử động</title>", "<title>VIP Girls Hierarchy — Xã hội tác tử lập luận phân cấp</title>")
    html = html.replace("content:'SOCIETY'", "content:'HIERARCHY'")
    html = _replace(html, '<div class="subtitle">Society · Xã hội tác tử động</div>', '<div class="subtitle">Hierarchy · Tác tử lập luận phân cấp</div>')
    html = _replace(html, '<div class="version">NGỮ NGHĨA · ĐỘNG LỰC XÃ HỘI</div>', '<div class="version">SUBAGENT · TRUYỀN TIN BẤT ĐỒNG BỘ</div>')
    html = html.replace('Society · Giám sát rủi ro lập luận', 'Hierarchy · Giám sát rủi ro theo thời điểm đến')
    html = _replace(html, "</style>", HIERARCHY_CSS + "\n</style>")
    html = _replace(html, "function metricsPanel(){", HIERARCHY_JS + "\nfunction metricsPanel(){")
    html = _replace(
        html,
        "function renderPanels(){if(state.edge!==null)interactionPanel();else reasoningPanel();enhanceReasoningPanel();activityPanel();societyPanel();eventsPanel();metricsPanel()}function render(){buttons();phase();renderGraph();decorateSocietyGraph();renderPanels()}",
        "function renderPanels(){if(state.edge!==null)interactionPanel();else reasoningPanel();enhanceReasoningPanel();activityPanel();societyPanel();eventsPanel();metricsPanel()}function render(){buttons();phase();renderGraph();decorateSocietyGraph();decorateHierarchyGraph();renderPanels();enhanceHierarchyPanel()}",
    )
    html = _replace(
        html,
        "function redrawDraggedGraph(){renderGraph();if(typeof decorateSocietyGraph==='function')decorateSocietyGraph();if(state.drag)",
        "function redrawDraggedGraph(){renderGraph();if(typeof decorateSocietyGraph==='function')decorateSocietyGraph();if(typeof decorateHierarchyGraph==='function')decorateHierarchyGraph();if(state.drag)",
    )
    html = _replace(
        html,
        "initLayoutControls();initNodeDragging();initRiskMonitoring();render();",
        "initLayoutControls();initNodeDragging();initRiskMonitoring();initHierarchy();render();",
    )
    html = html.replace("I=${item.T.toFixed(1)}", "I=${item.T_delta.toFixed(1)}")
    return html


HTML = _template()


def render_hierarchy_html(trace: dict[str, Any], mapping: dict[str, Any], output_path: Path) -> Path:
    html = HTML.replace("__TRACE__", _json(trace)).replace("__MAPPING__", _json(mapping))
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(html, encoding="utf-8")
    return output_path
